    buzz: h => [['R', 4, 2, 8, 1, h]],
    cap: h => [['R', 3, 1, 10, 2, h], ['R', 2, 3, 12, 1, h]],
    ponytail: h => [['R', 4, 2, 8, 2, h], ['R', 12, 2, 2, 3, h], ['R', 13, 4, 1, 6, h]],
    twintails: h => [['R', 4, 2, 8, 2, h], ['R', 2, 2, 2, 2, h], ['R', 1, 3, 2, 6, h], ['R', 12, 2, 2, 2, h], ['R', 13, 3, 2, 6, h]],
    afro: h => [['F', 8, 2.5, 3.8, h], ['R', 3, 3, 1, 4, h], ['R', 12, 3, 1, 4, h]],
